package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/mark3labs/mcp-go/server"
	mcptools "github.com/mvanhorn/printing-press-library/library/devices/synology-router/internal/mcp"
)

func main() {
	addr := flag.String("http", "", "HTTP address for streamable transport (e.g. :8080). Default: stdio.")
	flag.Parse()

	s := server.NewMCPServer(
		"Synology Router Manager",
		"1.0.0",
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	if *addr != "" {
		ss := server.NewStreamableHTTPServer(s)
		if err := ss.Start(*addr); err != nil {
			fmt.Fprintf(os.Stderr, "MCP HTTP server error: %v\n", err)
			os.Exit(1)
		}
		return
	}

	if err := server.ServeStdio(s); err != nil {
		fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
		os.Exit(1)
	}
}
